   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "amazon",
 "api_name": "show_product_reviews",
 "path": "/amazon/products/{product_id}/reviews",
 "method": "GET",
 "description": "Search or show a list of product reviews.",
 "parameters": [
  {
   "name": "product_id",
   "type": "integer",
   "required": true,
   "description": "ID of the product to show reviews for.",
   "default": null,
   "constraints": []
  },
  {
   "name": "query",
   "type": "string",
   "required": false,
   "description": "The search query string.",
   "default": "",
   "constraints": []
  },
  {
   "name": "user_email",
   "type": "string",
   "required": false,
   "description": "Email of the user to filter reviews by.",
   "default": null,
   "constraints": [
    "value is email address"
   ]
  },
  {
   "name": "min_rating",
   "type": "integer",
   "required": false,
   "description": "The minimum rating for a review.",
   "default": 1,
   "constraints": [
    "value >= 1, <= 5"
   ]
  },
  {
   "name": "max_rating",
   "type": "integer",
   "required": false,
   "description": "The maximum rating for a review.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 5"
   ]
  },
  {
   "name": "is_verified",
   "type": "boolean",
   "required": false,
   "description": "Filter reviews by whether they from a verified purchaser or not.",
   "default": null,
   "constraints": []
  },
  {
   "name": "page_index",
   "type": "integer",
   "required": false,
   "description": "The index of the page to return.",
   "default": 0,
   "constraints": [
    "value >= 0"
   ]
  },
  {
   "name": "page_limit",
   "type": "integer",
   "required": false,
   "description": "The maximum number of results to return per page.",
   "default": 5,
   "constraints": [
    "value >= 1, <= 20"
   ]
  },
  {
   "name": "sort_by",
   "type": "string",
   "required": false,
   "description": "The attribute to sort the product reviews by prefixed with +/- to reflect ascending/descending. Valid attributes: rating and created_at. If both query and sort_by are given and non-empty, results will be first ranked by query relevance, then paginated, and will then be sorted by the given attribute within each page.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": [
   {
    "review_id": 1,
    "product_id": 1,
    "is_verified": true,
    "rating": 1.0,
    "title": "string",
    "text": "string",
    "created_at": "2019-01-01T00:00:00",
    "user": {
     "name": "string",
     "email": "user@example.com"
    }
   }
  ],
  "failure": {
   "message": "string"
  }
 }
}

{
 "app_name": "supervisor",
 "api_name": "complete_task",
 "path": "/supervisor/message",
 "method": "POST",
 "description": "Mark the currently active task as complete with the given answer.",
 "parameters": [
  {
   "name": "answer",
   "type": "number | integer | string",
   "required": false,
   "description": "The answer to the task instruction. Pass it if and only if the task requests an answer, e.g., 'How many songs are in the Spotify queue?'. The answer must be concise, such as a number, a yes/no, or a specific entity, name, etc, e.g., '10' in this case. If the task is not a question, e.g., 'Start my Spotify music player.', the answer must be left to the default value, i.e., None.",
   "default": null,
   "constraints": []
  },
  {
   "name": "status",
   "type": "string",
   "required": false,
   "description": "Mark the task complete.",
   "default": "success",
   "constraints": [
    "value in ['success', 'fail']"
   ]
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}
